contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(dummy >= 0);
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        c.deposit{value: 0}(); if (__ESBMC_reverted()) return;
        uint256 afterDepositC = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && afterDepositC == beforeC && address(this).balance == beforeThis && address(c).balance == beforeC);
    }
    receive() external payable {}
}

